body:
Hello, I am trying to set up my LR2021 radio module to use CAD mode for duty-cycle receiving. This behavior is outlined in section 6.3.8 of the LR2021 datasheet. RadioLib does not include a method for configuring the SetRxDutyCycle SPI command to work in CAD mode, so I have been trying to implement the functionality myself. I have found that using the same testing setup, the existing StartReceiveDutyCycle method in RadioLib works perfectly, consistently receiving packets from my transmitter. However, this uses more power than what is theoretically possible in CAD mode, given that the full Rx demodulator is being used, and that there are more preamble symbols required to make a detection in the full-Rx mode.

Using my implementation for CAD mode, I am able to consistently detect incoming packets, and the module is seemingly switching to Rx mode, but readData consistently returns error -24. I've tested with increased preamble lengths, implicit headers, and verified the CAD exit mode macro, (Which appears to be ambiguous in RadioLib, 0x02 is a defined exit mode for SetCadParams in the datasheet, but not SetLoraCadParams which I think is the one actually used for duty-cycle receiving. In my code I use 0x01 to follow the datasheet for SetLoraCadParams.) and consistently have the same issue.

I'm not sure if my problem is an issue with the module itself, or if I'm just doing something wrong. Any help troubleshooting this would be greatly appreciated. Please let me know if there is any additional info/clarification I can provide.

--------------------------------------------------------------

<details><summary>Sketch #1 - Using Godmode & Custom RxDutyCycle methods to use setRxDutyCycle SPI command in CAD mode</summary>
<p>

```c++
// duty cycle cad rx using the spi command directly
// uses godmode for direct access to command from arduino


// enable godmode for direct spi command access
#define RADIOLIB_GODMODE (1)
// bashing radiolib with a hammer
#define protected public
// enable debug output
#define RADIOLIB_DEBUG_BASIC (1)
#define RADIOLIB_DEBUG_SPI (1)

#include <RadioLib.h>

/* CAD Parameters */
// 1-4 are supported, 'average required' is 1.5 so probably pick >=2
constexpr int CAD_SYMNUM = 4;
// based on symnum & spreading factor, SF=9 for cow radios
constexpr int CAD_DETPEAK = 56;
// shouldn't matter on rx side but try to keep it matched with tx
constexpr int PREAMBLE_LEN = 32;

/* Module Pins */
constexpr int PIN_NSS = 3;
constexpr int PIN_IRQ = 0;
constexpr int PIN_NRST = 2;
constexpr int PIN_BUSY = 1;

String teststr = "a q p     w";

// instantiate module
LR2021 radio = new Module(PIN_NSS, PIN_IRQ, PIN_NRST, PIN_BUSY);

volatile bool irqFlag = false;
void setFlag(void) {
  irqFlag = true;
}

// calculate duty cycle params for auto rx
// mostly just copied from radiolib function
int16_t LR2021CalcDutyCycleParams(LR2021* radio, uint16_t senderPreambleLength, uint16_t minSymbols, uint32_t* wakePeriod, uint32_t* sleepPeriod) {
  // calculate sleep & wake periods
  *wakePeriod = 0;
  *sleepPeriod = 0;
  DataRate_t dr = {
    .lora = {
      .spreadingFactor = radio->spreadingFactor,
      .bandwidth = radio->bandwidthKhz,
      .codingRate = radio->codingRate,
    }
  };
  int16_t state = radio->calculateRxDutyCycle(senderPreambleLength, radio->preambleLengthLoRa, minSymbols, &dr, wakePeriod, sleepPeriod);
  RADIOLIB_ASSERT(state);

  // duty cycle params returned via pointer
  return RADIOLIB_ERR_NONE;
}

// initialize duty cycle rx w/ cad
// just copying the library function
// must call AFTER initializing CAD
int16_t LR2021StartCadRxDutyCycle(LR2021* radio, uint32_t rxPeriod, uint32_t sleepPeriod, RadioLibIrqFlags_t irqFlags, RadioLibIrqFlags_t irqMask) {
  // datasheet claims time to go to sleep is ~500us, same to wake up, compensate for that with 1 ms + TCXO delay
  uint32_t transitionTime = radio->tcxoDelay + 1000;
  sleepPeriod -= transitionTime;

  // divide by 30.517 microseconds (RTC period, 1/32.768 kHz)
  // the datasheet claims the RTC frequency is 32 kHz; however, using that makes the timing inaccurate
  // so it looks like the actual value is the 32.768 kHz used on the previous LR11xx chips
  uint32_t rxPeriodRaw = (rxPeriod * 32768UL) / 1000000UL;
  uint32_t sleepPeriodRaw = (sleepPeriod * 32768UL) / 1000000UL;

  // check 24 bit limit and zero value (likely not intended)
  if ((rxPeriodRaw & 0xFF000000) || (rxPeriodRaw == 0)) {
    return (RADIOLIB_ERR_INVALID_RX_PERIOD);
  }

  // this check of the high byte also catches underflow when we subtracted transitionTime
  if ((sleepPeriodRaw & 0xFF000000) || (sleepPeriodRaw == 0)) {
    return (RADIOLIB_ERR_INVALID_SLEEP_PERIOD);
  }

  // set up Rx mode
  RadioModeConfig_t cfg = {
    .receive = {
      .timeout = RADIOLIB_LR2021_RX_TIMEOUT_INF,
      .irqFlags = irqFlags,
      .irqMask = irqMask,
      .len = 0,
    }
  };

  int16_t state = radio->stageMode(RADIOLIB_RADIO_MODE_RX, &cfg);
  RADIOLIB_ASSERT(state);

  // on LR2021, the second parameter is total period of the cycle, not the sleep duration
  // CAD option here should hopefully be the magic
  return (radio->setRxDutyCycle(rxPeriodRaw, rxPeriodRaw + sleepPeriodRaw, RADIOLIB_LR2021_RX_DUTY_CYCLE_MODE_CAD));
}

// cad initialization
int16_t LR2021CadInit(LR2021* radio, uint8_t cadSymbolNum, uint8_t detPeak, uint32_t rxPeriod) {
  // library uses wrong value for this, define correct code here
  const uint8_t cadExitModeRx = 0x01;

  uint8_t peak = detPeak;
  const uint8_t detPeakVals_2S[8] = { 56, 56, 56, 58, 58, 60, 64, 68 };
  const uint8_t detPeakVals_4S[8] = { 51, 51, 51, 54, 56, 60, 60, 64 };
  if (peak == RADIOLIB_LR2021_CAD_PARAM_DEFAULT) {
    // detpeak vals depend on symbol count
    // going to assume only 2 or 4 for now, 1-4 are listed on datasheet
    switch (cadSymbolNum) {
      case 2:
        // detPeak for 2 symbols
        peak = detPeakVals_2S[radio->spreadingFactor - 5];
        break;
      case 4:
        // detPeak for 4 symbols
        peak = detPeakVals_4S[radio->spreadingFactor - 5];
        break;
      default:
        Serial.println("invalid cad symbol number");
        return -1;
    }
  }

  // enable/disable fastCad
  // still depends on raising flag in radio properties
  uint8_t pnrDelta = radio->fastCad ? RADIOLIB_LR2021_LORA_CAD_PNR_DELTA_FAST : RADIOLIB_LR2021_LORA_CAD_PNR_DELTA_STANDARD;

  // timeout vals
  // in testing, there is some ambiguity on rx_max_time vs cad_timeout
  // we'll intentionally set both to play it safe
  uint32_t cadTimeoutRaw = (uint32_t)((float)rxPeriod * 32.0f);

  // set cad params
  int16_t state = radio->setLoRaCadParams(cadSymbolNum, false, pnrDelta, cadExitModeRx, cadTimeoutRaw, peak);
  RADIOLIB_ASSERT(state);

  return RADIOLIB_ERR_NONE;
}

// begin cad duty cycle
// will have to re-call after every Rx
int16_t startCAD(LR2021* radio, uint16_t preambleLen, uint16_t minSymbols, uint8_t cadSymNum, uint8_t detPeak) {
  uint32_t rxPeriod = 0;
  uint32_t sleepPeriod = 0;
  // manually declaring these because the library causes issues
  uint32_t genericIrqFlags = (1UL << RADIOLIB_IRQ_RX_DONE) | (1UL << RADIOLIB_IRQ_TIMEOUT);

  // calculate rx period & sleep period
  int16_t state = LR2021CalcDutyCycleParams(radio, preambleLen, minSymbols, &rxPeriod, &sleepPeriod);
  if (state != RADIOLIB_ERR_NONE) {
    Serial.println("error computing duty cycle params");
    return -1;
  }

  // set cad parameters
  state = LR2021CadInit(radio, cadSymNum, detPeak, rxPeriod);
  if (state != RADIOLIB_ERR_NONE) {
    Serial.println("error configuring CAD params");
    return -1;
  }

  // start cad rx
  // arbitratily doubling rxPeriod to see if that fixes things
  state = LR2021StartCadRxDutyCycle(radio, 10 * rxPeriod, sleepPeriod, genericIrqFlags, genericIrqFlags);
  if (state != RADIOLIB_ERR_NONE) {
    Serial.println("error starting cad rx");
    return -1;
  }

  Serial.println("started cad rx scan with params --- ");
  Serial.print("rx period: ");
  Serial.print(rxPeriod);
  Serial.print(", sleep period: ");
  Serial.println(sleepPeriod);
  return RADIOLIB_ERR_NONE;
}

void setup() {
  Serial.begin(9600);

  // Dio8 connects to D0 on mcu
  radio.irqDioNum = 8;
  // no tcxo module
  radio.tcxoVoltage = 0;
  //radio.fastCad = true;

  // taking potshots now
  //radio.implicitHeader(teststr.length());


  Serial.println("initializing LR2021 ...");
  ConfigLoRa_t config;
  config.frequency = 915;
  config.preambleLength = PREAMBLE_LEN;
  int state = radio.begin(config);
  if (state == RADIOLIB_ERR_NONE) {
    Serial.println("success!");
  } else {
    Serial.print("failed, code: ");
    Serial.println(state);
    // block futher execution
    while (true) { delay(10); }
  }

  // explicitly setting params to defaults
  radio.setSyncWord(0x12);
  radio.setGain(0);  // auto

  radio.setPacketReceivedAction(setFlag);

  Serial.println("beginning CAD RX test with following config ----- ");
  Serial.print("symNum - ");
  Serial.print(CAD_SYMNUM);
  Serial.print(", detPeak - ");
  Serial.print(CAD_DETPEAK);
  Serial.print(", preamble len - ");
  Serial.println(PREAMBLE_LEN);

  // start first scan
  state = startCAD(&radio, PREAMBLE_LEN, CAD_SYMNUM, CAD_SYMNUM, CAD_DETPEAK);
  if (state != RADIOLIB_ERR_NONE) {
    Serial.println("error starting cad rx");
    while (true) { delay(10); }
  }
}

int scans_run = 1;
int packets_rx = 0;
int failed_rx = 0;

void loop() {
  int state;
  if (irqFlag) {
    irqFlag = false;

    uint32_t irq = radio.getIrqFlags();
    radio.clearIrqFlags(RADIOLIB_LR2021_IRQ_ALL);

    Serial.println("irq triggered");
    Serial.println(irq);

    // detected a packet & tried to receive
    if (irq & RADIOLIB_LR2021_IRQ_RX_DONE) {
      String str;
      state = radio.readData(str);
      if (state == RADIOLIB_ERR_NONE) {
        packets_rx++;
        Serial.print("received packet # ");
        Serial.print(packets_rx);
        Serial.print(" on scan ");
        Serial.println(scans_run);
        Serial.print("\"");
        Serial.print(str);
        Serial.println("\"");
      } else {
        failed_rx++;
        Serial.print("failed to rx packet #");
        Serial.print(failed_rx);
        Serial.print(" on scan ");
        Serial.println(scans_run);
        Serial.print("error code: ");
        Serial.println(state);
      }
      float rssi = radio.getRSSI();
      float snr = radio.getSNR();
      Serial.println("received packet info");
      Serial.print("rssi: ");
      Serial.print(rssi);
      Serial.print(", snr: ");
      Serial.println(snr);
    }

    // scan timed out
    if (irq & RADIOLIB_LR2021_IRQ_TIMEOUT) {
      Serial.print("cad timeout on scan ");
      Serial.println(scans_run);
    }

    if (irq & RADIOLIB_LR2021_IRQ_RX_DONE || irq & RADIOLIB_LR2021_IRQ_TIMEOUT) {
      scans_run++;
      // let things chill out before starting again
      delay(10);
      // re-arm scan
      state = startCAD(&radio, PREAMBLE_LEN, CAD_SYMNUM, CAD_SYMNUM, CAD_DETPEAK);
      if (state != RADIOLIB_ERR_NONE) {
        Serial.println("error starting new scan");
        while (true) { delay(10); }
      }
    }
  }
}

